      it('Given sovereignty hubs exist, When I request hubs, Then I should receive hub data with online status and upgrades', async () => {
        // Given
        const expectedHubs = [
          {
            structure_id: 100000001,
            system_id: 30000142,
            corporation_id: 98000002,
            alliance_id: 99000006,
