            remaining_reagents: 500,
            installed_upgrades: [1, 2, 3],
          },
          {
            structure_id: 100000002,
            system_id: 30004759,
            corporation_id: 98000003,
            alliance_id: 99000001,
            online: false,
            remaining_reagents: 0,
            installed_upgrades: [],
          },
        ];

        jest
          .spyOn(client.skyhooks, 'getSovereigntyHubs')
