 * ESI.ts Example: Mercenary Dens & Tactical Operations
 *
 * Fetches mercenary dens across New Eden and their spawned
 * tactical operations (MTOs), showing development and anarchy levels.
 *
 * Usage: npm run example:mercenary
 */
import { EsiClient } from '../src/EsiClient';

async function main() {
  const client = new EsiClient();

  try {
    console.log('Mercenary Dens & Tactical Operations\n');

    const [dens, operations] = await Promise.all([
      client.mercenary.getMercenaryDens(),
      client.mercenary.getMercenaryTacticalOperations(),
    ]);

    // Dens grouped by region
    const byRegion = new Map<number, typeof dens>();
    for (const den of dens) {
      const list = byRegion.get(den.region_id) || [];
      list.push(den);
      byRegion.set(den.region_id, list);
    }

    console.log('Mercenary Dens by Region');
    console.log('-'.repeat(60));
    const sortedRegions = [...byRegion.entries()].sort((a, b) => b[1].length - a[1].length);

    for (const [regionId, regionDens] of sortedRegions.slice(0, 10)) {
      const avgDev =
        regionDens.reduce((sum, d) => sum + (d.development_level ?? 0), 0) / regionDens.length;
      const avgAnarchy =
        regionDens.reduce((sum, d) => sum + (d.anarchy_level ?? 0), 0) / regionDens.length;
      console.log(
        `  Region ${regionId}: ${regionDens.length} den(s) — ` +
          `Avg Dev: ${avgDev.toFixed(1)} — Avg Anarchy: ${avgAnarchy.toFixed(1)}`,
      );
    }
    if (sortedRegions.length > 10) console.log(`  ... and ${sortedRegions.length - 10} more`);

    // Tactical operations summary
    console.log(`\nTactical Operations (${operations.length} total)`);
    console.log('-'.repeat(60));

    const byStatus = new Map<string, number>();
    for (const op of operations) {
      byStatus.set(op.status, (byStatus.get(op.status) || 0) + 1);
    }
    for (const [status, count] of byStatus) {
      console.log(`  ${status.padEnd(12)} ${count}`);
    }

    const active = operations.filter(op => op.status === 'active');
    if (active.length > 0) {
      console.log('\nActive Operations (first 5)');
      console.log('-'.repeat(60));
      for (const op of active.slice(0, 5)) {
        const expires = op.expires_at ? ` — Expires: ${op.expires_at}` : '';
        console.log(`  Den ${op.den_id} → System ${op.system_id} — ${op.site_type}${expires}`);
      }
    }
  } catch (err) {
    console.error('Error:', err instanceof Error ? err.message : err);
    process.exit(1);
  } finally {
    await client.shutdown();
  }
}

main();
"}

Write {"file_path":"D:\code\ESI.ts\examples\access-lists.ts","content":"/**
 * ESI.ts Example: Access Lists
 *
 * Retrieves an access list (ACL) and displays its entries
 * grouped by entity type. Requires ESI authentication.
 *
 * Usage: npm run example:access-lists
 *
 * Environment:
 *   ESI_ACCESS_TOKEN — a valid SSO token with the access-lists scope
 */
import { EsiClient } from '../src/EsiClient';
import { EsiError } from '../src/core/util/error';

const ACCESS_LIST_ID = 1;

async function main() {
  const client = new EsiClient({ clientId: 'esi-ts-access-lists-example' });

  try {
    console.log(`Access List #${ACCESS_LIST_ID}\n`);

    const list = await client.accessLists.getAccessList(ACCESS_LIST_ID);

    console.log(`Name:    ${list.name}`);
    console.log(`ID:      ${list.access_list_id}`);
    console.log(`Entries: ${list.entries.length}`);
    console.log('-'.repeat(60));

    // Group entries by entity type
    const byType = new Map<string, typeof list.entries>();
    for (const entry of list.entries) {
      const group = byType.get(entry.entity_type) || [];
      group.push(entry);
      byType.set(entry.entity_type, group);
    }

    for (const [entityType, entries] of byType) {
      console.log(`\n${entityType.charAt(0).toUpperCase() + entityType.slice(1)}s (${entries.length})`);
      for (const entry of entries.slice(0, 10)) {
        const icon = entry.access_type === 'allowed' ? '+' : '-';
        console.log(`  [${icon}] ${entry.entity_type} ${entry.entity_id} — ${entry.access_type}`);
      }
      if (entries.length > 10) console.log(`  ... and ${entries.length - 10} more`);
    }
  } catch (err) {
    if (err instanceof EsiError && err.status === 401) {
      console.error('Authentication required. Set ESI_ACCESS_TOKEN to a valid SSO token.');
    } else {
      console.error('Error:', err instanceof Error ? err.message : err);
    }
    process.exit(1);
  } finally {
    await client.shutdown();
  }
}

main();
"}

